mapper.select:
SELECT A.FINPROD_ID id, A.FINPROD_MARKET_ID || ':' || A.FINPROD_ABBR text, A.FINPROD_NAME, TO_CHAR(A.VDATE, 'yyyy-MM-dd') VDATE, TO_CHAR(A.MDATE, 'yyyy-MM-dd') MDATE, TO_CHAR(A.IDATE, 'yyyy-MM-dd') IDATE, A.TRADE_MARKET, A.CCY, A.CALENDAR_ID, basisData.BASIS, B.TYPE_4 windtypeone, A.FINPROD_MARKET_ID, A.IS_RIGHT, A.REGIST_ORG FROM FIN_PRODUCT A LEFT JOIN FIN_PRODUCT_ADD FPA ON FPA.FINPROD_ID = A.FINPROD_ID LEFT JOIN FIN_PRODUCT_TYPE B ON B.FINPROD_ID = A.FINPROD_ID LEFT JOIN ( select max(BASIS) as BASIS, FINPROD_ID from FIN_CASH_CALC_RULE
AND FINPROD_ID = #{initValue}
group by FINPROD_ID ) basisData on A.FINPROD_ID = basisData.FINPROD_ID
A.TRADE_MARKET =#{tradePlace,jdbcType=VARCHAR}
AND ( A.FINPROD_MARKET_ID LIKE CONCAT('%', CONCAT(#{search}, '%')) or A.FINPROD_NAME LIKE CONCAT('%', CONCAT(#{search}, '%')) or A.FINPROD_ABBR LIKE CONCAT('%', CONCAT(#{search}, '%')) )
AND A.FINPROD_ID = #{initValue}
AND A.FINPROD_TYPE2 = #{FINPROD_TYPE_TG_F01}
AND B.TYPE_4 in
#{item}
AND (FPA.IS_ISSUE_ASSET IS NULL OR FPA.IS_ISSUE_ASSET = 'N')

SELECT fp.FINPROD_MARKET_ID bondCode, fp.FINPROD_ABBR bondAbbrName, fp.FINPROD_ID finprodId, fp.MDATE mdate, mbvi.NETPRICE firstNetPrice, fp.REGIST_ORG repRegistOrg,
fpt.type_6 secType
FROM FIN_PRODUCT fp
LEFT JOIN FIN_PRODUCT_ADD FPA ON FPA.FINPROD_ID = fp.FINPROD_ID
left join fin_product_type fpt2 on fp.finprod_id=fpt2.finprod_id and fpt2.type_8='F01'
LEFT JOIN MST_BOND_VALUATION_INFO mbvi ON mbvi.SEC_ID = fp.FINPROD_MARKET_ID AND mbvi.VALUE_DATE <= TO_DATE(#{plateDate, jdbcType=VARCHAR}, 'yyyy-MM-dd') AND NOT EXISTS ( SELECT 1 FROM MST_BOND_VALUATION_INFO mbviInner WHERE mbviInner.SEC_ID = fp.FINPROD_MARKET_ID AND mbviInner.VALUE_DATE <= TO_DATE(#{plateDate, jdbcType=VARCHAR}, 'yyyy-MM-dd') AND mbviInner.VALUE_DATE > mbvi.VALUE_DATE ) LEFT JOIN FIN_PRODUCT_TYPE FPT ON fp.FINPROD_ID = FPT.FINPROD_ID
fp.FINPROD_TYPE2 = #{FINPROD_TYPE_TG_F01} AND (FPA.IS_ISSUE_ASSET IS NULL OR FPA.IS_ISSUE_ASSET = 'N')
AND fp.TRADE_MARKET = #{tradeMarket, jdbcType=VARCHAR}
AND fp.FINPROD_MARKET_ID = #{bondCode, jdbcType=VARCHAR}
AND fp.REGIST_ORG in
#{item}
AND FPT.TYPE_4 in
#{item, jdbcType=VARCHAR}
AND fp.TRADE_MARKET = #{tradeMarket}
AND fp.TRADE_MARKET = #{tradePlace}
AND fp.mdate >= to_date(#{mdate},'yyyy-MM-dd')

SELECT distinct fp.FINPROD_MARKET_ID bondCode, fp.FINPROD_ABBR bondAbbrName, fp.FINPROD_ID finprodId, fp.MDATE mdate,
(NVL(ava.AMOUNT, 0) - NVL(pledge.AMOUNT, 0) + nvl(AVA_FLOW.amount, 0)) * 100 avaPledgePrin, NVL(pledgeList.PLEDGE_NUMBER, 0) * 100 pledgePrin, NVL(pledgeList.PLEDGE_NUMBER, 0) * 100 pledgePrinInit, mbvi.NETPRICE firstNetPrice, pledgeList.PLEDGE_RATIO*100 pledgeRatio, nvl(ava.AMOUNT,0) * 100 prin, fp.REGIST_ORG repRegistOrg
,pledgeList.bussId entrustId
FROM (
SELECT ENTRUST_ID bussId, FINPROD_ID pledgeId, PLEDGE_FACE_VALUE, PLEDGE_NUMBER, PLEDGE_RATIO, PLEDGE_AMT FROM ETR_PLEDGE WHERE ENTRUST_ID = #{entrustId} union all SELECT ENTRUST_ID bussId, FINPROD_ID pledgeId, PLEDGE_FACE_VALUE, PLEDGE_NUMBER, PLEDGE_RATIO, PLEDGE_AMT FROM WFL_ETR_PLEDGE WHERE ENTRUST_ID = #{entrustId}
SELECT fdp.FINPROD_ID bussId, fdp.PLEDGE_FINPROD_ID pledgeId, fdp.PLEDGE_FACE_VALUE, fdp.PLEDGE_NUMBER, fdp.PLEDGE_RATIO, fdp.PLEDGE_AMT FROM FIN_DEAL_PLEDGE fdp LEFT JOIN TRD_PRODUCT_DEAL tpd ON tpd.TRADE_ID = fdp.FINPROD_ID WHERE (tpd.IS_CANCEL = #{YES_OR_NO_N} AND fdp.FINPROD_ID = #{bizCode}) OR ( tpd.trade_status = '03' AND SUBSTR(FDP.FINPROD_ID, 0, LENGTH(#{bizCode})) = #{bizCode} )
) pledgeList LEFT JOIN (
select PSP.FINPROD_ID FINPROD_ID,PSP.SEC_ACCT_ID, SUM(DECODE(PSP.HODING_TYPE,'06',-PSP.AMOUNT,'11',-PSP.AMOUNT,PSP.AMOUNT)) AMOUNT from PTL_SEC_POSITION PSP LEFT JOIN FIN_PRODUCT T ON PSP.FINPROD_ID = T.FINPROD_ID WHERE T.FINPROD_TYPE2 = 'F01' and psp.PORTFOLIO_ID = #{portfolioId, jdbcType=VARCHAR} AND psp.CDATE <= TO_DATE(#{plateDate, jdbcType=VARCHAR}, 'yyyy-MM-dd') and PSP.HODING_TYPE IN (#{POSITION_TYPE_01}, #{POSITION_TYPE_03},#{POSITION_TYPE_05},'06', '11', '08')
AND PSP.SEC_ACCT_ID = #{SEC_ACCT_ID, jdbcType=VARCHAR}
and psp.cdate = (select max(cdate) from PTL_SEC_POSITION tt where tt.portfolio_id = psp.portfolio_id and tt.sec_acct_id = psp.sec_acct_id and tt.finprod_id = psp.finprod_id AND tt.CDATE <= TO_DATE(#{plateDate, jdbcType=VARCHAR}, 'yyyy-MM-dd') and tt.branch = psp.branch and tt.inv_aim = psp.inv_aim and tt.hoding_type = psp.hoding_type and tt.ccy = psp.ccy ) GROUP BY psp.finprod_id,psp.SEC_ACCT_ID
) ava ON ava.FINPROD_ID = pledgeList.pledgeId LEFT JOIN ( select sum(decode(PSP.HODING_TYPE, '12', -1*psp.AMOUNT, psp.amount)) AMOUNT, psp.finprod_id, psp.SEC_ACCT_ID
,INV_AIM
from PTL_SEC_POSITION_FLOW PSP INNER JOIN FIN_PRODUCT T ON PSP.FINPROD_ID = T.FINPROD_ID AND T.FINPROD_TYPE2 = 'F01' and psp.PORTFOLIO_ID = #{portfolioId, jdbcType=VARCHAR} AND psp.CDATE <= TO_DATE(#{plateDate, jdbcType=VARCHAR}, 'yyyy-MM-dd') and PSP.HODING_TYPE IN ('01', '12')
AND PSP.SEC_ACCT_ID = #{secAcctId, jdbcType=VARCHAR}
AND PSP.SEC_ACCT_ID = #{chlId, jdbcType=VARCHAR}
and PSP.TRADE_ID != #{folwtradeId, jdbcType=VARCHAR}
AND NOT EXISTS (SELECT 1 FROM PTL_SEC_POSITION_FLOW PSP1 WHERE PSP1.portfolio_id = psp.portfolio_id and PSP1.sec_acct_id = psp.sec_acct_id and PSP1.finprod_id = psp.finprod_id AND PSP1.CDATE <= TO_DATE(#{plateDate, jdbcType=VARCHAR},'yyyy-MM-dd') and PSP1.CDATE > psp.CDATE and PSP1.branch = psp.branch and PSP1.inv_aim = psp.inv_aim and PSP1.hoding_type = psp.hoding_type and PSP1.ccy = psp.ccy) group by PSP.finprod_id, psp.SEC_ACCT_ID
,INV_AIM
) AVA_FLOW ON ava.FINPROD_ID = AVA_FLOW.FINPROD_ID and ava.SEC_ACCT_ID= AVA_FLOW.SEC_ACCT_ID LEFT JOIN ( SELECT FINPROD_ID, SUM(NVL(AMOUNT, 0)) AMOUNT FROM PTL_SEC_POSITION WHERE PORTFOLIO_ID = #{portfolioId, jdbcType=VARCHAR} AND CDATE = TO_DATE(#{plateDate, jdbcType=VARCHAR}, 'yyyy-MM-dd') AND HODING_TYPE = #{POSITION_TYPE_04} GROUP BY FINPROD_ID ) pledge ON pledge.FINPROD_ID = pledgeList.pledgeId INNER JOIN FIN_PRODUCT fp ON fp.FINPROD_ID = pledgeList.pledgeId LEFT JOIN MST_BOND_VALUATION_INFO mbvi ON mbvi.SEC_ID = fp.FINPROD_MARKET_ID AND mbvi.VALUE_DATE <= TO_DATE(#{plateDate, jdbcType=VARCHAR}, 'yyyy-MM-dd') AND NOT EXISTS ( SELECT 1 FROM MST_BOND_VALUATION_INFO mbviInner WHERE mbviInner.SEC_ID = fp.FINPROD_MARKET_ID AND mbviInner.VALUE_DATE <= TO_DATE(#{plateDate, jdbcType=VARCHAR}, 'yyyy-MM-dd') AND mbviInner.VALUE_DATE > mbvi.VALUE_DATE ) AND mbvi.VALUE_SOURCE IN (SELECT BVSD.VALUATION_PRICE FROM bok_VAL_SCHEME_DETAIL BVSD LEFT JOIN FIN_PRODUCT FBN ON FBN.TRADE_MARKET = BVSD.TRADE_MARKET WHERE FBN.FINPROD_MARKET_ID = fp.FINPROD_MARKET_ID AND BVSD.VALUATION_PRICE IS NOT NULL AND BVSD.SCHEME_ID = 'SCHEME001')

SELECT pledgeList.entrustId entrustId, pledgeList.portfolioId portfolioId, pledgeList.portfolioName portfolioName, pledgeList.prinAmt prinAmt, pledgeList.prinAmt entrustSurAmt, pledgeList.secAcctId secAcctId, pledgeList.rebackPrice*100 rebackPrice, fp.FINPROD_MARKET_ID bondCode, fp.FINPROD_ID finprodId, fp.FINPROD_ABBR bondAbbrName, fp.MDATE mdate, (NVL(ava.AMOUNT, 0) - NVL(pledge.AMOUNT, 0)) * 100 avaPledgePrin, NVL(pledgeList.PLEDGE_NUMBER, 0) * 100 pledgePrin, NVL(pledgeList.PLEDGE_NUMBER, 0) * 100 pledgePrinInit, mbvi.NETPRICE firstNetPrice, pledgeList.PLEDGE_RATIO*100 pledgeRatio, nvl(ava.AMOUNT,0) * 100 prin, fp.REGIST_ORG repRegistOrg FROM (
SELECT a.entrust_id entrustId, b.portfolio_id portfolioId, c.finprod_name portfolioName, d.sec_acct_id secAcctId, b.Price rebackPrice, a.FINPROD_ID pledgeId, a.PLEDGE_FACE_VALUE, a.PLEDGE_NUMBER, a.PLEDGE_RATIO, a.PLEDGE_AMT, b.entrust_amt prinAmt FROM ETR_PLEDGE a inner join ETR_ENTRUST b on a.entrust_id = b.entrust_id inner join ETR_ENTRUST_ADD d on b.entrust_id=d.entrust_id inner join fin_product c on b.portfolio_id=c.finprod_market_id WHERE
a.ENTRUST_ID in
#{item}
union all SELECT a.entrust_id entrustId, b.portfolio_id portfolioId, c.finprod_name portfolioName, d.sec_acct_id secAcctId, b.Price rebackPrice, a.FINPROD_ID pledgeId, a.PLEDGE_FACE_VALUE, a.PLEDGE_NUMBER, a.PLEDGE_RATIO, a.PLEDGE_AMT, b.entrust_amt prinAmt FROM WFL_ETR_PLEDGE a inner join WFL_ETR_ENTRUST b on a.entrust_id = b.entrust_id inner join WFL_ETR_ENTRUST_ADD d on b.entrust_id=d.entrust_id inner join fin_product c on b.portfolio_id=c.finprod_market_id WHERE
a.ENTRUST_ID in
#{item}
) pledgeList LEFT JOIN ( SELECT FINPROD_ID, SUM(NVL(AMOUNT, 0)) AMOUNT FROM PTL_SEC_POSITION WHERE PORTFOLIO_ID = #{portfolioId, jdbcType=VARCHAR} AND CDATE = TO_DATE(#{plateDate, jdbcType=VARCHAR}, 'yyyy-MM-dd') AND HODING_TYPE IN (#{POSITION_TYPE_01}, #{POSITION_TYPE_03}, #{POSITION_TYPE_05}) and SEC_ACCT_ID = #{SEC_ACCT_ID} GROUP BY FINPROD_ID ) ava ON ava.FINPROD_ID = pledgeList.pledgeId LEFT JOIN ( SELECT FINPROD_ID, SUM(NVL(AMOUNT, 0)) AMOUNT FROM PTL_SEC_POSITION WHERE PORTFOLIO_ID = #{portfolioId, jdbcType=VARCHAR} AND CDATE = TO_DATE(#{plateDate, jdbcType=VARCHAR}, 'yyyy-MM-dd') AND HODING_TYPE = #{POSITION_TYPE_04} GROUP BY FINPROD_ID ) pledge ON pledge.FINPROD_ID = pledgeList.pledgeId INNER JOIN FIN_PRODUCT fp ON fp.FINPROD_ID = pledgeList.pledgeId LEFT JOIN MST_BOND_VALUATION_INFO mbvi ON mbvi.SEC_ID = fp.FINPROD_MARKET_ID AND mbvi.VALUE_DATE <= TO_DATE(#{plateDate, jdbcType=VARCHAR}, 'yyyy-MM-dd') AND NOT EXISTS ( SELECT 1 FROM MST_BOND_VALUATION_INFO mbviInner WHERE mbviInner.SEC_ID = fp.FINPROD_MARKET_ID AND mbviInner.VALUE_DATE <= TO_DATE(#{plateDate, jdbcType=VARCHAR}, 'yyyy-MM-dd') AND mbviInner.VALUE_DATE > mbvi.VALUE_DATE ) AND mbvi.VALUE_SOURCE IN (SELECT BVSD.VALUATION_PRICE FROM bok_VAL_SCHEME_DETAIL BVSD LEFT JOIN FIN_PRODUCT FBN ON FBN.TRADE_MARKET = BVSD.TRADE_MARKET WHERE FBN.FINPROD_MARKET_ID = fp.FINPROD_MARKET_ID AND BVSD.VALUATION_PRICE IS NOT NULL AND BVSD.SCHEME_ID = 'SCHEME001')

SELECT pledgeList.entrustId entrustId, pledgeList.portfolioId portfolioId, pledgeList.portfolioName portfolioName, pledgeList.prinAmt prinAmt, pledgeList.prinAmt entrustSurAmt, pledgeList.secAcctId secAcctId, pledgeList.rebackPrice*100 rebackPrice, fp.FINPROD_ID, fp.FINPROD_MARKET_ID bondCode, fp.FINPROD_ABBR bondAbbrName, fp.MDATE mdate, '' avaPledgePrin, NVL(pledgeList.PLEDGE_NUMBER, 0) * 100 pledgePrin, mbvi.NETPRICE firstNetPrice, pledgeList.PLEDGE_RATIO*100 pledgeRatio, '' prin, fp.REGIST_ORG repRegistOrg FROM (
SELECT a.entrust_id entrustId, b.portfolio_id portfolioId, c.finprod_name portfolioName, d.sec_acct_id secAcctId, b.Price rebackPrice, a.FINPROD_ID pledgeId, a.PLEDGE_FACE_VALUE, a.PLEDGE_NUMBER, a.PLEDGE_RATIO, a.PLEDGE_AMT, b.entrust_amt prinAmt FROM ETR_PLEDGE a inner join ETR_ENTRUST b on a.entrust_id = b.entrust_id inner join ETR_ENTRUST_ADD d on b.entrust_id=d.entrust_id inner join fin_product c on b.portfolio_id=c.finprod_market_id WHERE
a.ENTRUST_ID in
#{item}
union all SELECT a.entrust_id entrustId, b.portfolio_id portfolioId, c.finprod_name portfolioName, d.sec_acct_id secAcctId, b.Price rebackPrice, a.FINPROD_ID pledgeId, a.PLEDGE_FACE_VALUE, a.PLEDGE_NUMBER, a.PLEDGE_RATIO, a.PLEDGE_AMT, b.entrust_amt prinAmt FROM WFL_ETR_PLEDGE a inner join WFL_ETR_ENTRUST b on a.entrust_id = b.entrust_id inner join WFL_ETR_ENTRUST_ADD d on b.entrust_id=d.entrust_id inner join fin_product c on b.portfolio_id=c.finprod_market_id WHERE
a.ENTRUST_ID in
#{item}
) pledgeList LEFT JOIN FIN_PRODUCT fp ON fp.FINPROD_MARKET_ID = SUBSTR(pledgeList.pledgeId, 5) AND fp.FINPROD_TYPE2 = #{FINPROD_TYPE_TG_F01} LEFT JOIN MST_BOND_VALUATION_INFO mbvi ON mbvi.SEC_ID = fp.FINPROD_MARKET_ID AND mbvi.VALUE_DATE <= TO_DATE(#{plateDate, jdbcType=VARCHAR}, 'yyyy-MM-dd') AND NOT EXISTS ( SELECT 1 FROM MST_BOND_VALUATION_INFO mbviInner WHERE mbviInner.SEC_ID = fp.FINPROD_MARKET_ID AND mbviInner.VALUE_DATE <= TO_DATE(#{plateDate, jdbcType=VARCHAR}, 'yyyy-MM-dd') AND mbviInner.VALUE_DATE > mbvi.VALUE_DATE )

SELECT fp.FINPROD_ID finprodId, fp.FINPROD_MARKET_ID bondCode, fp.FINPROD_ABBR bondAbbrName, fp.MDATE mdate, '' avaPledgePrin, NVL(pledgeList.PLEDGE_NUMBER, 0) * 100 pledgePrin, mbvi.NETPRICE firstNetPrice, pledgeList.PLEDGE_RATIO*100 pledgeRatio, '' prin, fp.REGIST_ORG repRegistOrg
,pledgeList.bussId entrustId
FROM (
SELECT ENTRUST_ID bussId, FINPROD_ID pledgeId, PLEDGE_FACE_VALUE, PLEDGE_NUMBER, PLEDGE_RATIO, PLEDGE_AMT FROM ETR_PLEDGE WHERE ENTRUST_ID = #{entrustId} union all SELECT ENTRUST_ID bussId, FINPROD_ID pledgeId, PLEDGE_FACE_VALUE, PLEDGE_NUMBER, PLEDGE_RATIO, PLEDGE_AMT FROM WFL_ETR_PLEDGE WHERE ENTRUST_ID = #{entrustId}
SELECT fdp.FINPROD_ID bussId, fdp.PLEDGE_FINPROD_ID pledgeId, fdp.PLEDGE_FACE_VALUE, fdp.PLEDGE_NUMBER, fdp.PLEDGE_RATIO, fdp.PLEDGE_AMT FROM FIN_DEAL_PLEDGE fdp LEFT JOIN TRD_PRODUCT_DEAL tpd ON tpd.TRADE_ID = fdp.FINPROD_ID WHERE (tpd.IS_CANCEL = #{YES_OR_NO_N} AND fdp.FINPROD_ID = #{bizCode}) OR ( tpd.trade_status = '03' AND SUBSTR(FDP.FINPROD_ID, 0, LENGTH(#{bizCode})) = #{bizCode} )
) pledgeList LEFT JOIN FIN_PRODUCT fp ON fp.FINPROD_MARKET_ID = SUBSTR(pledgeList.pledgeId, 5) AND fp.FINPROD_TYPE2 = #{FINPROD_TYPE_TG_F01} LEFT JOIN MST_BOND_VALUATION_INFO mbvi ON mbvi.SEC_ID = fp.FINPROD_MARKET_ID AND mbvi.VALUE_DATE <= TO_DATE(#{plateDate, jdbcType=VARCHAR}, 'yyyy-MM-dd') AND NOT EXISTS ( SELECT 1 FROM MST_BOND_VALUATION_INFO mbviInner WHERE mbviInner.SEC_ID = fp.FINPROD_MARKET_ID AND mbviInner.VALUE_DATE <= TO_DATE(#{plateDate, jdbcType=VARCHAR}, 'yyyy-MM-dd') AND mbviInner.VALUE_DATE > mbvi.VALUE_DATE )

SELECT fp.FINPROD_MARKET_ID bondCode, ETR_ENTRUST_PLEDGE.FINPROD_ID finprodId, fp.FINPROD_ABBR bondAbbrName, fp.MDATE mdate, fp.REGIST_ORG repRegistOrg, MBCR.GRADE_RESULT gradeResult, mbvi.LAST_PERIOD endDays1, ava.SEC_ACCT_ID secAcctId, (NVL(ava.AMOUNT, 0) + NVL(AVA_FLOW.amount, 0)) * 100 prin, NVL(pledge.AMOUNT, 0) * 100 pledgePrin, NVL(pledge.AMOUNT, 0) * 100 pledgePrinInit, (NVL(ava.AMOUNT, 0) - NVL(pledge.AMOUNT, 0) + NVL(AVA_FLOW.amount, 0)) * 100 avaPledgePrin, mbvi.NETPRICE firstNetPrice,
fpt.type_6 secType
,CASE WHEN ava.INV_AIM = #{INV_AIM_AC} THEN 1 WHEN ava.INV_AIM = #{INV_AIM_FVOCI} THEN 2 WHEN ava.INV_AIM = #{INV_AIM_FVTPL} THEN 3 ELSE 0 END invAimSort, ava.INV_AIM invAim
FROM ETR_ENTRUST_PLEDGE LEFT JOIN ( select PSP.FINPROD_ID,psp.PORTFOLIO_ID,
INV_AIM,
SUM(DECODE(PSP.HODING_TYPE,#{POSITION_TYPE_06},-PSP.AMOUNT,'11',-PSP.AMOUNT,PSP.AMOUNT)) AMOUNT, psp.SEC_ACCT_ID from PTL_SEC_POSITION PSP LEFT JOIN FIN_PRODUCT T ON PSP.FINPROD_ID = T.FINPROD_ID LEFT JOIN FIN_PRODUCT FPSAI ON PSP.SEC_ACCT_ID = FPSAI.FINPROD_ID WHERE T.FINPROD_TYPE2 = #{FINPROD_TYPE_TG_F01} and psp.PORTFOLIO_ID = #{portfolioId, jdbcType=VARCHAR} AND psp.CDATE <= TO_DATE(#{plateDate, jdbcType=VARCHAR}, 'yyyy-MM-dd') and PSP.HODING_TYPE IN (#{POSITION_TYPE_01},#{POSITION_TYPE_03},#{POSITION_TYPE_05},#{POSITION_TYPE_06}, '11','08')
AND PSP.SEC_ACCT_ID = #{secAcctId, jdbcType=VARCHAR}
AND PSP.SEC_ACCT_ID = #{chlId, jdbcType=VARCHAR}
AND (FPSAI.FINPROD_ID is null or FPSAI.FINPROD_TYPE2 !='F28')
and psp.cdate = (select max(cdate) from PTL_SEC_POSITION tt where tt.portfolio_id = psp.portfolio_id and tt.sec_acct_id = psp.sec_acct_id and tt.finprod_id = psp.finprod_id AND tt.CDATE <= TO_DATE(#{plateDate, jdbcType=VARCHAR}, 'yyyy-MM-dd') and tt.branch = psp.branch and tt.inv_aim = psp.inv_aim and tt.hoding_type = psp.hoding_type and tt.ccy = psp.ccy ) GROUP BY psp.finprod_id, psp.PORTFOLIO_ID,psp.SEC_ACCT_ID
,INV_AIM
)AVA ON ETR_ENTRUST_PLEDGE.PORTFOLIO_ID = AVA.PORTFOLIO_ID AND ETR_ENTRUST_PLEDGE.FINPROD_ID = AVA.FINPROD_ID AND ETR_ENTRUST_PLEDGE.SEC_ACCT_ID = AVA.SEC_ACCT_ID LEFT JOIN ( select sum(decode(PSP.HODING_TYPE, '12', -1*psp.AMOUNT, psp.amount)) AMOUNT, psp.finprod_id, psp.SEC_ACCT_ID
,INV_AIM
from PTL_SEC_POSITION_FLOW PSP INNER JOIN FIN_PRODUCT T ON PSP.FINPROD_ID = T.FINPROD_ID AND T.FINPROD_TYPE2 =#{FINPROD_TYPE_TG_F01} and psp.PORTFOLIO_ID = #{portfolioId, jdbcType=VARCHAR} AND psp.CDATE <= TO_DATE(#{plateDate, jdbcType=VARCHAR}, 'yyyy-MM-dd') and PSP.HODING_TYPE IN (#{POSITION_TYPE_01}, '12')
AND PSP.SEC_ACCT_ID = #{secAcctId, jdbcType=VARCHAR}
AND PSP.SEC_ACCT_ID = #{chlId, jdbcType=VARCHAR}
and PSP.TRADE_ID != #{folwtradeId, jdbcType=VARCHAR}
AND NOT EXISTS (SELECT 1 FROM PTL_SEC_POSITION_FLOW PSP1 WHERE PSP1.portfolio_id = psp.portfolio_id and PSP1.sec_acct_id = psp.sec_acct_id and PSP1.finprod_id = psp.finprod_id AND PSP1.CDATE <= TO_DATE(#{plateDate, jdbcType=VARCHAR},'yyyy-MM-dd') and PSP1.CDATE > psp.CDATE and PSP1.branch = psp.branch and PSP1.inv_aim = psp.inv_aim and PSP1.hoding_type = psp.hoding_type and PSP1.ccy = psp.ccy) group by PSP.finprod_id, psp.SEC_ACCT_ID
,INV_AIM
) AVA_FLOW ON ava.FINPROD_ID = AVA_FLOW.FINPROD_ID and ava.SEC_ACCT_ID= AVA_FLOW.SEC_ACCT_ID
AND ava.INV_AIM = AVA_FLOW.INV_AIM
INNER JOIN FIN_PRODUCT T ON ava.FINPROD_ID = T.FINPROD_ID LEFT JOIN ( SELECT RANK() OVER(PARTITION BY O_CODE ORDER BY GRADE_DATE DESC, DECODE(GRADE_ORG_ID,'22',NULL, GRADE_ORG_ID), grade_result DESC, O_TYPE) NUM, O_CODE, GRADE_RESULT FROM MST_BOND_CREDIT_RATING WHERE GRADE_DATE <= TO_DATE(#{plateDate, jdbcType=VARCHAR},'yyyy-MM-dd') ) MBCR ON MBCR.O_CODE = T.FINPROD_MARKET_ID AND MBCR.NUM = 1 LEFT JOIN ( SELECT PSP.FINPROD_ID,
PSP.INV_AIM,
SUM(NVL(PSP.AMOUNT, 0)) AMOUNT, psp.SEC_ACCT_ID FROM PTL_SEC_POSITION PSP WHERE PSP.PORTFOLIO_ID = #{portfolioId, jdbcType=VARCHAR} AND PSP.CDATE <= TO_DATE(#{plateDate, jdbcType=VARCHAR}, 'yyyy-MM-dd') AND PSP.HODING_TYPE = #{POSITION_TYPE_04}
AND PSP.SEC_ACCT_ID = #{secAcctId, jdbcType=VARCHAR}
AND PSP.SEC_ACCT_ID = #{chlId, jdbcType=VARCHAR}
AND NOT EXISTS (SELECT 1 FROM PTL_SEC_POSITION PSP1 WHERE PSP1.portfolio_id = psp.portfolio_id and PSP1.sec_acct_id = psp.sec_acct_id and PSP1.finprod_id = psp.finprod_id AND PSP1.CDATE <= TO_DATE(#{plateDate, jdbcType=VARCHAR},'yyyy-MM-dd') and PSP1.CDATE > psp.CDATE and PSP1.branch = psp.branch and PSP1.inv_aim = psp.inv_aim and PSP1.hoding_type = psp.hoding_type and PSP1.ccy = psp.ccy) GROUP BY PSP.FINPROD_ID, psp.SEC_ACCT_ID
,INV_AIM
) pledge ON pledge.FINPROD_ID = ava.FINPROD_ID and pledge.SEC_ACCT_ID = ava.SEC_ACCT_ID
AND pledge.INV_AIM = ava.INV_AIM
INNER JOIN FIN_PRODUCT fp ON fp.FINPROD_ID = ava.FINPROD_ID
AND fp.FINPROD_TYPE2 = #{FINPROD_TYPE_TG_F01}
AND fp.TRADE_MARKET = #{tradeMarket}
LEFT JOIN MST_BOND_VALUATION_INFO mbvi ON mbvi.SEC_ID = fp.FINPROD_MARKET_ID AND mbvi.VALUE_DATE <= TO_DATE(#{plateDate, jdbcType=VARCHAR},'yyyy-MM-dd') AND mbvi.VALUE_SOURCE ='CBC' AND NOT EXISTS ( SELECT 1 FROM MST_BOND_VALUATION_INFO mbviInner WHERE mbviInner.SEC_ID = fp.FINPROD_MARKET_ID AND mbviInner.VALUE_DATE <= TO_DATE(#{plateDate, jdbcType=VARCHAR},'yyyy-MM-dd') AND mbviInner.VALUE_SOURCE ='CBC' AND mbviInner.VALUE_DATE > mbvi.VALUE_DATE ) LEFT JOIN FIN_PRODUCT_TYPE FPT ON fp.FINPROD_ID = FPT.FINPROD_ID
AND ava.AMOUNT > 0 AND NVL(ava.AMOUNT, 0) - NVL(pledge.AMOUNT, 0) + nvl(AVA_FLOW.amount, 0) > 0 AND ETR_ENTRUST_PLEDGE.PORTFOLIO_ID= #{portfolioId, jdbcType=VARCHAR}
AND fp.REGIST_ORG in
#{item}
AND fp.FINPROD_MARKET_ID = #{bondCode, jdbcType=VARCHAR}
AND FPT.TYPE_4 in
#{item, jdbcType=VARCHAR}
AND mbvi.LAST_PERIOD >= to_number(#{endDays1Start})
AND mbvi.LAST_PERIOD <= to_number(#{endDays1End})
ORDER BY CASE WHEN ava.INV_AIM = #{INV_AIM_AC} THEN 1 WHEN ava.INV_AIM = #{INV_AIM_FVOCI} THEN 2 WHEN ava.INV_AIM = #{INV_AIM_FVTPL} THEN 3 ELSE 0 END

SELECT fp.FINPROD_MARKET_ID bondCode, fp.FINPROD_ID finprodId, fp.FINPROD_ABBR bondAbbrName, fp.MDATE mdate,
fp.REGIST_ORG repRegistOrg, MBCR.GRADE_RESULT gradeResult, mbvi.LAST_PERIOD endDays1, ava.SEC_ACCT_ID secAcctId,
(NVL(ava.AMOUNT, 0) + nvl(AVA_FLOW.amount, 0)) * 100 prin, NVL(pledge.AMOUNT, 0) * 100 pledgePrin, NVL(pledge.AMOUNT, 0) * 100 pledgePrinInit, (NVL(ava.AMOUNT, 0) - NVL(pledge.AMOUNT, 0) + nvl(AVA_FLOW.amount, 0)) * 100 avaPledgePrin, mbvi.NETPRICE firstNetPrice,
fpt.type_6 secType
, CASE WHEN ava.INV_AIM = #{INV_AIM_AC} THEN 1 WHEN ava.INV_AIM = #{INV_AIM_FVOCI} THEN 2 WHEN ava.INV_AIM = #{INV_AIM_FVTPL} THEN 3 ELSE 0 END invAimSort, ava.INV_AIM invAim
FROM (select PSP.FINPROD_ID,
INV_AIM,
SUM(DECODE(PSP.HODING_TYPE,#{POSITION_TYPE_06},-PSP.AMOUNT,'11',-PSP.AMOUNT,PSP.AMOUNT)) AMOUNT, psp.SEC_ACCT_ID from PTL_SEC_POSITION PSP LEFT JOIN FIN_PRODUCT T ON PSP.FINPROD_ID = T.FINPROD_ID WHERE T.FINPROD_TYPE2 = #{FINPROD_TYPE_TG_F01} and psp.PORTFOLIO_ID = #{portfolioId, jdbcType=VARCHAR} AND psp.CDATE <= TO_DATE(#{plateDate, jdbcType=VARCHAR}, 'yyyy-MM-dd') and PSP.HODING_TYPE IN (#{POSITION_TYPE_01}, #{POSITION_TYPE_03},#{POSITION_TYPE_05},#{POSITION_TYPE_06}, '11', '08')
AND PSP.SEC_ACCT_ID = #{secAcctId, jdbcType=VARCHAR}
AND PSP.SEC_ACCT_ID = #{chlId, jdbcType=VARCHAR}
and psp.cdate = (select max(cdate) from PTL_SEC_POSITION tt where tt.portfolio_id = psp.portfolio_id and tt.sec_acct_id = psp.sec_acct_id and tt.finprod_id = psp.finprod_id AND tt.CDATE <= TO_DATE(#{plateDate, jdbcType=VARCHAR}, 'yyyy-MM-dd') and tt.branch = psp.branch and tt.inv_aim = psp.inv_aim and tt.hoding_type = psp.hoding_type and tt.ccy = psp.ccy ) GROUP BY psp.finprod_id, psp.SEC_ACCT_ID
,INV_AIM
)ava LEFT JOIN ( select sum(decode(PSP.HODING_TYPE, '12', -1*psp.AMOUNT, psp.amount)) AMOUNT, psp.finprod_id, psp.SEC_ACCT_ID
,INV_AIM
from PTL_SEC_POSITION_FLOW PSP INNER JOIN FIN_PRODUCT T ON PSP.FINPROD_ID = T.FINPROD_ID AND T.FINPROD_TYPE2 = #{FINPROD_TYPE_TG_F01} and psp.PORTFOLIO_ID = #{portfolioId, jdbcType=VARCHAR} AND psp.CDATE <= TO_DATE(#{plateDate, jdbcType=VARCHAR}, 'yyyy-MM-dd') and PSP.HODING_TYPE IN (#{POSITION_TYPE_01}, '12')
AND PSP.SEC_ACCT_ID = #{secAcctId, jdbcType=VARCHAR}
AND PSP.SEC_ACCT_ID = #{chlId, jdbcType=VARCHAR}
and PSP.TRADE_ID != #{folwtradeId, jdbcType=VARCHAR}
AND NOT EXISTS (SELECT 1 FROM PTL_SEC_POSITION_FLOW PSP1 WHERE PSP1.portfolio_id = psp.portfolio_id and PSP1.sec_acct_id = psp.sec_acct_id and PSP1.finprod_id = psp.finprod_id AND PSP1.CDATE <= TO_DATE(#{plateDate, jdbcType=VARCHAR}, 'yyyy-MM-dd') and PSP1.CDATE > psp.CDATE and PSP1.branch = psp.branch and PSP1.inv_aim = psp.inv_aim and PSP1.hoding_type = psp.hoding_type and PSP1.ccy = psp.ccy) group by PSP.finprod_id, psp.SEC_ACCT_ID
,INV_AIM
) AVA_FLOW ON ava.FINPROD_ID = AVA_FLOW.FINPROD_ID and ava.SEC_ACCT_ID = AVA_FLOW.SEC_ACCT_ID
AND ava.INV_AIM = AVA_FLOW.INV_AIM
INNER JOIN FIN_PRODUCT T ON ava.FINPROD_ID = T.FINPROD_ID LEFT JOIN ( SELECT RANK() OVER(PARTITION BY O_CODE ORDER BY GRADE_DATE DESC, DECODE(GRADE_ORG_ID,'22',NULL, GRADE_ORG_ID), grade_result DESC, O_TYPE) NUM, O_CODE, GRADE_RESULT FROM MST_BOND_CREDIT_RATING WHERE GRADE_DATE <= TO_DATE(#{plateDate, jdbcType=VARCHAR}, 'yyyy-MM-dd') ) MBCR ON MBCR.O_CODE = T.FINPROD_MARKET_ID AND MBCR.NUM = 1 LEFT JOIN ( SELECT PSP.FINPROD_ID,
PSP.INV_AIM,
SUM(NVL(PSP.AMOUNT, 0)) AMOUNT, psp.SEC_ACCT_ID FROM PTL_SEC_POSITION PSP WHERE PSP.PORTFOLIO_ID = #{portfolioId, jdbcType=VARCHAR} AND PSP.CDATE <= TO_DATE(#{plateDate, jdbcType=VARCHAR}, 'yyyy-MM-dd') AND PSP.HODING_TYPE = #{POSITION_TYPE_04}
AND PSP.SEC_ACCT_ID = #{secAcctId, jdbcType=VARCHAR}
AND PSP.SEC_ACCT_ID = #{chlId, jdbcType=VARCHAR}
AND NOT EXISTS (SELECT 1 FROM PTL_SEC_POSITION PSP1 WHERE PSP1.portfolio_id = psp.portfolio_id and PSP1.sec_acct_id = psp.sec_acct_id and PSP1.finprod_id = psp.finprod_id AND PSP1.CDATE <= TO_DATE(#{plateDate, jdbcType=VARCHAR}, 'yyyy-MM-dd') and PSP1.CDATE > psp.CDATE and PSP1.branch = psp.branch and PSP1.inv_aim = psp.inv_aim and PSP1.hoding_type = psp.hoding_type and PSP1.ccy = psp.ccy) GROUP BY PSP.FINPROD_ID, psp.SEC_ACCT_ID
,INV_AIM
) pledge ON pledge.FINPROD_ID = ava.FINPROD_ID and pledge.SEC_ACCT_ID = ava.SEC_ACCT_ID
AND pledge.INV_AIM = ava.INV_AIM
INNER JOIN FIN_PRODUCT fp ON fp.FINPROD_ID = ava.FINPROD_ID
AND fp.FINPROD_TYPE2 = #{FINPROD_TYPE_TG_F01}
AND fp.TRADE_MARKET = #{tradeMarket}
LEFT JOIN MST_BOND_VALUATION_INFO mbvi ON mbvi.SEC_ID = fp.FINPROD_MARKET_ID AND mbvi.VALUE_DATE <= TO_DATE(#{plateDate, jdbcType=VARCHAR}, 'yyyy-MM-dd') AND mbvi.VALUE_SOURCE ='CBC' AND NOT EXISTS ( SELECT 1 FROM MST_BOND_VALUATION_INFO mbviInner WHERE mbviInner.SEC_ID = fp.FINPROD_MARKET_ID AND mbviInner.VALUE_DATE <= TO_DATE(#{plateDate, jdbcType=VARCHAR}, 'yyyy-MM-dd') AND mbviInner.VALUE_SOURCE ='CBC' AND mbviInner.VALUE_DATE > mbvi.VALUE_DATE ) LEFT JOIN FIN_PRODUCT_TYPE FPT ON fp.FINPROD_ID = FPT.FINPROD_ID
AND ava.AMOUNT > 0 AND NVL(ava.AMOUNT, 0) - NVL(pledge.AMOUNT, 0) + nvl(AVA_FLOW.amount, 0) > 0
AND fp.REGIST_ORG in
#{item}
AND fp.FINPROD_MARKET_ID = #{bondCode, jdbcType=VARCHAR}
AND FPT.TYPE_4 in
#{item, jdbcType=VARCHAR}
AND mbvi.LAST_PERIOD >= to_number(#{endDays1Start})
AND mbvi.LAST_PERIOD <= to_number(#{endDays1End})
