,INV_AIM
)ava LEFT JOIN ( select sum(decode(PSP.HODING_TYPE, '12', -1*psp.AMOUNT, psp.amount)) AMOUNT, psp.finprod_id, psp.SEC_ACCT_ID,psp.portfolio_id
,INV_AIM
from PTL_SEC_POSITION_FLOW PSP INNER JOIN FIN_PRODUCT T ON PSP.FINPROD_ID = T.FINPROD_ID AND T.FINPROD_TYPE2 = #{FINPROD_TYPE_TG_F01}
and psp.PORTFOLIO_ID in
