#{item}
AND PSP.CDATE <= TO_DATE(#{plateDate, jdbcType=VARCHAR}, 'yyyy-MM-dd') AND PSP.HODING_TYPE = #{POSITION_TYPE_04}
AND PSP.SEC_ACCT_ID = #{secAcctId, jdbcType=VARCHAR}
AND PSP.SEC_ACCT_ID = #{chlId, jdbcType=VARCHAR}
AND NOT EXISTS (SELECT 1 FROM PTL_SEC_POSITION PSP1 WHERE PSP1.portfolio_id = psp.portfolio_id and PSP1.sec_acct_id = psp.sec_acct_id and PSP1.finprod_id = psp.finprod_id AND PSP1.CDATE <= TO_DATE(#{plateDate, jdbcType=VARCHAR}, 'yyyy-MM-dd') and PSP1.CDATE > psp.CDATE and PSP1.branch = psp.branch and PSP1.inv_aim = psp.inv_aim and PSP1.hoding_type = psp.hoding_type and PSP1.ccy = psp.ccy) GROUP BY PSP.FINPROD_ID, psp.SEC_ACCT_ID,psp.portfolio_id
,INV_AIM
