ORDER BY CASE WHEN ava.INV_AIM = #{INV_AIM_AC} THEN 1 WHEN ava.INV_AIM = #{INV_AIM_FVOCI} THEN 2 WHEN ava.INV_AIM = #{INV_AIM_FVTPL} THEN 3 ELSE 0 END

SELECT fp.FINPROD_MARKET_ID bondCode, fp.FINPROD_ID finprodId, fp.FINPROD_ABBR bondAbbrName, fp.MDATE mdate, fp.REGIST_ORG repRegistOrg, MBCR.GRADE_RESULT gradeResult, mbvi.LAST_PERIOD endDays1, ava.SEC_ACCT_ID secAcctId, NVL(ava.pledStrdPrinAmt, 0) prin, NVL(ava.pledgeAmount, 0) pledgePrin, NVL(ava.pledgeAmount, 0) pledgePrinInit, NVL(ava.pledStrdPrinAmt, 0) avaPledgePrin, mbvi.NETPRICE firstNetPrice, fpt.type_6 secType ,pp.portfolio_id ,pp.PORTFOLIO_NAME FROM ( SELECT TEMP.PORTFOLIO_ID, /*组合代码*/ TEMP.PORTFOLIO_NAME, TEMP.SEC_ACCT_ID, /*证券账户/通道代码*/ TEMP.FINPROD_ID, /*分支序号*/ SUM(TEMP.pledStrdPrinAmt) pledStrdPrinAmt, /*可质押券面总额*/ SUM(TEMP.pledgeAmount) pledgeAmount /*已质押质押券面总额*/ FROM ( SELECT psp.PORTFOLIO_ID, pp.PORTFOLIO_NAME, psp.SEC_ACCT_ID, psp.FINPROD_ID, pp.VDATE, CASE WHEN ppc.S_HOLDINGTYPE = 'S_002' THEN psp.AMOUNT*nvl(ppc.CAL_FLAG,1) ELSE 0 END AS pledStrdPrinAmt, /*可质押券面总额*/ CASE WHEN psp.HODING_TYPE in ('A_012','A_032') THEN psp.AMOUNT*nvl(ppc.CAL_FLAG,1) ELSE 0 END AS pledgeAmount /*已质押质押券面总额*/ FROM
ETR_SEC_POSITION_RULE psp
PTL_SEC_POSITION_RULE psp
INNER JOIN ETR_PLEDGE ep ON ep.ENTRUST_ID=#{entrustId} and ep.FINPROD_ID = psp.FINPROD_ID
INNER JOIN PTL_PORTFOLIO pp ON psp.PORTFOLIO_ID = pp.PORTFOLIO_ID left JOIN PTL_POSITION_CFG ppc ON psp.HODING_TYPE =ppc.HOLDINGTYPE AND ppc.S_HOLDINGTYPE ='S_002' WHERE 1 = 1 AND psp.CDATE = to_date(#{plateDate, jdbcType=VARCHAR},'yyyy-MM-dd')/*组合持仓.日期 = 平台日*/ AND psp.DATE_TYPE =0 AND ( ppc.S_HOLDINGTYPE ='S_002' or psp.HODING_TYPE in ('A_012','A_032'))
and psp.PORTFOLIO_ID =#{portfolioId}
) TEMP WHERE 1 = 1 GROUP BY TEMP.PORTFOLIO_ID, TEMP.PORTFOLIO_NAME, TEMP.SEC_ACCT_ID, TEMP.FINPROD_ID, TEMP.VDATE HAVING SUM(TEMP.pledStrdPrinAmt) > 0 /*只统计可质押券面总额>0*/ )ava INNER JOIN FIN_PRODUCT fp ON fp.FINPROD_ID = ava.FINPROD_ID AND fp.FINPROD_TYPE2 = #{FINPROD_TYPE_TG_F01}
AND fp.TRADE_MARKET = #{tradeMarket}
LEFT JOIN ( SELECT RANK() OVER(PARTITION BY O_CODE ORDER BY GRADE_DATE DESC, DECODE(GRADE_ORG_ID,'22',NULL, GRADE_ORG_ID), grade_result DESC, O_TYPE) NUM, O_CODE, GRADE_RESULT FROM MST_BOND_CREDIT_RATING WHERE GRADE_DATE <= TO_DATE(#{plateDate, jdbcType=VARCHAR}, 'yyyy-MM-dd') ) MBCR ON MBCR.O_CODE = fp.FINPROD_MARKET_ID AND MBCR.NUM = 1
LEFT JOIN MST_BOND_VALUATION_INFO mbvi ON mbvi.SEC_ID = fp.FINPROD_MARKET_ID AND mbvi.VALUE_DATE <= TO_DATE(#{plateDate, jdbcType=VARCHAR}, 'yyyy-MM-dd') AND mbvi.VALUE_SOURCE ='CBC' AND NOT EXISTS ( SELECT 1 FROM MST_BOND_VALUATION_INFO mbviInner WHERE mbviInner.SEC_ID = fp.FINPROD_MARKET_ID AND mbviInner.VALUE_DATE <= TO_DATE(#{plateDate, jdbcType=VARCHAR}, 'yyyy-MM-dd') AND mbviInner.VALUE_SOURCE ='CBC' AND mbviInner.VALUE_DATE > mbvi.VALUE_DATE ) LEFT JOIN FIN_PRODUCT_TYPE FPT ON fp.FINPROD_ID = FPT.FINPROD_ID left join PTL_PORTFOLIO pp on pp.portfolio_id = ava.portfolio_id LEFT JOIN FIN_PRODUCT_ADD FPA ON FPA.FINPROD_ID = fp.FINPROD_ID
AND (FPA.IS_ISSUE_ASSET IS NULL OR FPA.IS_ISSUE_ASSET = 'N')
AND fp.REGIST_ORG in
#{item}
AND fp.FINPROD_MARKET_ID = #{bondCode, jdbcType=VARCHAR}
AND FPT.TYPE_4 in
#{item, jdbcType=VARCHAR}
AND mbvi.LAST_PERIOD >= to_number(#{endDays1Start})
AND mbvi.LAST_PERIOD <= to_number(#{endDays1End})
